<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
if (!ekstra_is_admin()) deny_access();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$action=$_POST['action']??'';if($action==='add'){ $kode=strtoupper(trim((string)($_POST['kode']??'')));$nama=trim((string)($_POST['nama']??''));$ket=trim((string)($_POST['keterangan']??''));if($kode===''||$nama==='')$error='Kode dan nama ekstrakurikuler wajib diisi.';else{$st=$pdo->prepare('SELECT id FROM ekstrakurikuler WHERE kode=? LIMIT 1');$st->execute([$kode]);if($st->fetch())$error='Kode ekstrakurikuler sudah digunakan.';else{$pdo->prepare('INSERT INTO ekstrakurikuler(kode,nama,aktif,keterangan) VALUES(?,?,1,?)')->execute([$kode,$nama,$ket!==''?$ket:null]);redirect('ekstrakurikuler/index.php');}}}elseif($action==='toggle'){$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE ekstrakurikuler SET aktif=IF(aktif=1,0,1) WHERE id=?')->execute([$id]);redirect('ekstrakurikuler/index.php');}}
$activeTp=(int)($pdo->query("SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY tanggal_mulai DESC,id DESC LIMIT 1")->fetchColumn() ?: 0);
$stRows=$pdo->prepare("SELECT e.*, (SELECT COUNT(*) FROM ekstra_anggota ea WHERE ea.ekstrakurikuler_id=e.id AND ea.tahun_pelajaran_id=? AND ea.status='aktif') anggota FROM ekstrakurikuler e ORDER BY e.nama");
$stRows->execute([$activeTp]);$rows=$stRows->fetchAll();
$page_title='Ekstrakurikuler';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main extra-page"><header class="topbar"><div class="topbar-title">Ekstrakurikuler</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1>Master Ekstrakurikuler</h1><p>Master kegiatan dipisahkan dari penugasan guru dan histori Tapel.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-card"><h2><i class="bi bi-trophy"></i> Tambah Ekstrakurikuler</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="dashboard-grid" style="grid-template-columns:1fr 1fr"><label>Kode<input name="kode" class="form-control" placeholder="PRAMUKA" required></label><label>Nama<input name="nama" class="form-control" placeholder="Pramuka" required></label><label style="grid-column:1/-1">Keterangan<textarea name="keterangan" class="form-control" rows="2"></textarea></label></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan</button></div></form></div><div class="dashboard-table-card"><div class="section-title"><div><h2>Daftar Ekstrakurikuler</h2></div></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Kode</th><th>Nama</th><th>Anggota Aktif</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty-state">Belum ada ekstrakurikuler.</td></tr><?php else:foreach($rows as $r):?><tr><td><code><?=e($r['kode'])?></code></td><td><strong><?=e($r['nama'])?></strong></td><td><?= (int)$r['anggota']?></td><td><span class="status-badge <?=$r['aktif']?'status-aktif':'status-nonaktif'?>"><?=$r['aktif']?'Aktif':'Nonaktif'?></span></td><td><a class="btn btn-sm btn-primary" href="<?=BASE_URL?>ekstrakurikuler/anggota.php?extra_id=<?=$r['id']?>&menu=ekstra_anggota">Anggota</a> <a class="btn btn-sm btn-secondary" href="<?=BASE_URL?>ekstrakurikuler/jadwal.php?extra_id=<?=$r['id']?>&menu=ekstra_jadwal">Jadwal</a> <form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-icon-sm <?=$r['aktif']?'btn-warning':'btn-success'?>" title="<?=$r['aktif']?'Nonaktifkan':'Aktifkan'?> ekstrakurikuler" aria-label="<?=$r['aktif']?'Nonaktifkan':'Aktifkan'?> ekstrakurikuler"><i class="bi <?=$r['aktif']?'bi-pause-circle':'bi-check-circle'?>" aria-hidden="true"></i></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php'; ?>